L(OA14, 2,
  "Este cuaderno y un lápiz.",
  "Aprenderé a usar conectores (palabras que unen ideas y ordenan los hechos) para que mi narración se entienda mejor.",
  ["Sé que una narración tiene inicio, desarrollo y desenlace.", "Sé escribir oraciones completas."],
  ["Los conectores son palabras o expresiones que unen oraciones y muestran cómo se relacionan. En una narración usamos conectores de tiempo, que ordenan los hechos: primero, luego, después, mientras, de pronto, finalmente, al día siguiente. Sin ellos, los hechos parecen sueltos.",
   "También usamos conectores de causa y consecuencia: «porque» explica por qué ocurrió algo («Corrí porque llegaba tarde») y «por eso» muestra el resultado («Llegaba tarde; por eso corrí»). Los conectores de contraste, como «pero» y «sin embargo», muestran una oposición («Quería jugar, pero estaba lloviendo»).",
   "Para elegir un conector, me pregunto qué relación hay entre las ideas: ¿una ocurre antes que la otra?, ¿una explica la otra?, ¿se oponen? Usar siempre «y luego» hace aburrida la lectura; variar los conectores hace el relato más claro y ágil."],
  [("conector", "palabra que une ideas y muestra su relación"), ("de tiempo", "ordena los hechos: primero, luego, finalmente"), ("de causa", "explica por qué ocurrió algo: porque"), ("de consecuencia", "muestra el resultado: por eso"), ("de contraste", "muestra oposición: pero, sin embargo")],
  [("Elegir el conector", "«Estaba cansado, ____ seguí caminando». ¿Qué conector usas: pero o porque?",
    ["Las ideas se oponen: cansado y seguí.", "Se oponen.", "Uso «pero»."], "pero"),
   ("Ordenar con conectores", "Hechos: se levantó, desayunó, salió. Escribe una oración con primero, luego y finalmente.",
    ["Ordeno los hechos.", "Uso los conectores.", "Primero se levantó, luego desayunó y finalmente salió."], "Primero se levantó, luego desayunó y finalmente salió")],
  [("Usar solo «y luego» en toda la narración.", "Se vuelve repetitiva.", "Varía los conectores."),
   ("Usar «porque» cuando quiero mostrar el resultado.", "«Porque» explica la causa, no el resultado.", "Usa «por eso» para el resultado.")],
  ([E("«Primero», «luego» y «finalmente», ¿son conectores de tiempo? Responde sí o no.", "Sí", "Ordenan los hechos."),
    E("«Corrí ____ llegaba tarde». ¿Qué conector va: porque o pero?", "porque", "Explica la causa."),
    E("«Quería jugar, ____ llovía». ¿Qué conector va: pero o porque?", "pero", "Hay una oposición entre querer jugar y llover.")],
   [E("«Llovía; ____ nos quedamos en casa». Elige: por eso o pero.", "por eso", "Muestra la consecuencia de que llovía."),
    E("«____ hizo la tarea, jugó con su perro». Elige el conector de tiempo: Después de que o Pero.", "Después de que", "Ordena los hechos."),
    E("«De pronto» indica algo inesperado en el tiempo. ¿Es un conector de tiempo? Responde sí o no.", "Sí", "Marca un momento repentino.")],
   [E("Une con el conector correcto: «Ana estudió mucho / aprobó la prueba». Elige: por eso o pero.", "por eso", "La segunda idea es el resultado de la primera."),
    E("Ordena con conectores de tiempo: «bajé las escaleras» / «abrí la puerta» / «salí a la calle». ¿Qué conectores usas en orden? Elige: primero, luego, finalmente.", "Primero, luego, finalmente", "Ordenan tres hechos."),
    arith("Una narración usa 4 conectores de tiempo, 3 de causa y 2 de contraste. ¿Cuántos conectores usa?", "4+3+2", "Se suman todos.", " conectores")],
   [E("Una estudiante escribe: «Salí y luego fui y luego comí y luego dormí». ¿Qué problema tiene el texto? Responde: repite el conector o falta el final.", "Repite el conector", "Usa siempre «y luego»."),
    E("«Estaba nervioso, ____ salió bien». ¿Cuál conector expresa contraste: pero o porque?", "pero", "Nervioso se opone a salir bien.")],
   [E("Completa con un conector de causa: «Se mojó ____ no llevaba paraguas».", "porque", "Explica por qué se mojó."),
    E("Completa con el conector adecuado para marcar el cierre: «____ llegamos a casa». Elige: Finalmente o Primero.", "Finalmente", "Marca el final de la secuencia.")]),
  [E("Quieres contar: «Salimos tarde. Perdimos el bus». Une las ideas con un conector de consecuencia. Elige: por eso o aunque.", "por eso", "La segunda idea es la consecuencia de la primera.")],
  [E("¿Qué es un conector?", "Una palabra que une ideas", "Muestra cómo se relacionan."),
   E("Nombra un conector de tiempo.", "Primero, luego, después, mientras, de pronto o finalmente", "Ordenan los hechos."),
   E("¿«Pero» expresa contraste? Responde sí o no.", "Sí", "«Pero» muestra una oposición entre ideas.")],
  ("Escribe cuatro oraciones que cuenten lo que hiciste ayer desde que despertaste. Usa al menos un conector de tiempo, uno de causa («porque») y uno de contraste («pero»). Subraya los conectores.",
   "Primero me levanté. Desayuné rápido porque tenía hambre. Quería jugar, pero tenía tarea. Finalmente, me dormí temprano.",
   ["al menos tres tipos de conector", "los hechos van en orden", "conectores subrayados"], ["las oraciones en el cuaderno"],
   ["repetir el mismo conector", "usar porque como resultado"], "Léelas a alguien y pídele que identifique los conectores."),
  "Cuenta oralmente tu mañana usando primero, luego y finalmente.",
  "Escribe cinco oraciones con conectores distintos.")

