L(OA14, 3,
  "Este cuaderno y un lápiz.",
  "Aprenderé a escribir descripciones de personajes y de ambientes con adjetivos, detalles de los sentidos y comparaciones.",
  ["Sé usar conectores en una narración.", "Sé que un adjetivo dice cómo es algo."],
  ["Una descripción dice cómo es algo o alguien. En una narración, las descripciones ayudan al lector a imaginar a los personajes y el ambiente. Para describir un personaje, puedo decir cómo se ve (alto, de pelo rizado), cómo actúa (siempre ayuda) y cómo se siente (nervioso).",
   "Para describir un ambiente uso los sentidos: lo que se ve, se oye, se huele, se toca o se saborea. En vez de decir «la cocina era bonita», puedo escribir «la cocina olía a pan recién hecho y la luz entraba por la ventana». Los detalles concretos hacen que el lector sienta que está allí.",
   "Las comparaciones también ayudan: «sus manos eran frías como el hielo». Pero describir no significa llenar la narración de adjetivos. Elijo detalles que muestran algo importante del personaje o preparan lo que va a pasar. Si un detalle no aporta, lo quito."],
  [("descripción", "texto que dice cómo es algo o alguien"), ("adjetivo", "palabra que dice cómo es un sustantivo"), ("detalle", "dato concreto que ayuda a imaginar"), ("sentidos", "vista, oído, olfato, tacto y gusto"), ("comparación", "unir dos cosas con «como»")],
  [("Descripción con sentidos", "Mejora «La cocina era linda» con un olor y un sonido.",
    ["Pienso en un olor.", "Pienso en un sonido.", "Los uno en una oración."], "La cocina olía a pan recién hecho y la tetera silbaba"),
   ("Mostrar al personaje", "En vez de «Pedro era generoso», escribe una acción que lo muestre.",
    ["Pienso en algo que haría una persona generosa.", "Compartir.", "Pedro partió su colación y la repartió con sus amigos."], "Pedro partió su colación y la repartió con sus amigos")],
  [("Poner muchos adjetivos sin detalle.", "El lector no logra imaginar nada concreto.", "Usa pocos adjetivos y detalles que se vean u oigan."),
   ("Describir todo y detener la historia.", "Se pierde el interés.", "Elige solo los detalles importantes.")],
  ([E("Un adjetivo dice cómo es algo. ¿Verdadero o falso?", "Verdadero", "Un adjetivo describe cómo es algo."),
    E("«Olía a pan recién hecho». ¿Qué sentido usa: olfato o vista?", "Olfato", "Habla de un olor."),
    E("«Sus manos eran frías como el hielo». ¿Es una comparación? Responde sí o no.", "Sí", "Une dos cosas usando «como».")],
   [E("«El perro ladraba fuerte». ¿Qué sentido aparece: oído o gusto?", "Oído", "Habla de un sonido."),
    E("Elige la descripción con detalles concretos: a) «Era un lugar bonito». b) «Había árboles altos y se oía el canto de los pájaros». Escribe la letra.", "b", "Tiene detalles que se ven y se oyen."),
    E("«Lía sonreía siempre y ayudaba a todos». ¿Qué rasgo del personaje muestra: ser amable o ser tímida?", "Ser amable", "Sus acciones lo muestran.")],
   [E("Describe con un sentido de la vista: ¿cuál oración usa un detalle visual? a) «La playa tenía arena dorada». b) «La playa olía a sal». Escribe la letra.", "a", "Dorada se ve."),
    E("Convierte en comparación: «La luna era blanca». ¿Cuál agrega «como»? a) «La luna era blanca como un plato». b) «La luna era blanca».", "a", "Une la luna con un plato."),
    arith("Un texto tiene 4 oraciones de descripción y 6 de acción. ¿Cuántas oraciones tiene en total?", "4+6", "Se suman las oraciones.", " oraciones")],
   [E("Un estudiante escribe 10 adjetivos seguidos: «Era un niño alto, flaco, bueno, listo, simpático...». ¿Es una buena descripción? Responde sí o no.", "No", "Enumera sin mostrar detalles."),
    E("En la narración «Salió corriendo hacia la plaza», ¿qué detalle de ambiente agregarías para mostrar que es de noche: a) «Las estrellas brillaban y el aire estaba frío» o b) «Era un lugar muy lindo»? Escribe la letra.", "a", "Es un detalle concreto.")],
   [E("Describe al personaje: «Mario estaba asustado». Elige la versión que lo muestra con una acción: a) «Mario tragó saliva y sus manos temblaban». b) «Mario sintió miedo». Escribe la letra.", "a", "Muestra el miedo con acciones."),
    E("Si un detalle no ayuda a entender al personaje ni lo que va a pasar, ¿qué haces: lo quitas o lo dejas igual?", "Lo quitas", "No aporta a la narración.")]),
  [E("Quieres describir el patio del colegio en un día de lluvia. ¿Cuál es el mejor detalle: «el suelo brillaba mojado y se oía el golpeteo de las gotas» o «era un patio»?", "El suelo brillaba mojado y se oía el golpeteo de las gotas", "Usa detalles de la vista y el oído.")],
  [E("En Lenguaje: ¿Qué es un detalle?", "Un dato concreto que ayuda a imaginar", "Hace más clara la descripción."),
   E("Nombra un sentido.", "Vista, oído, olfato, tacto o gusto", "Son los cinco."),
   E("¿Conviene llenar la narración de adjetivos? Responde sí o no.", "No", "Hay que elegir detalles importantes.")],
  ("Describe en cuatro o cinco oraciones a un personaje y el lugar donde está. Usa estos tres elementos: un personaje (un abuelo pescador, una niña con una mochila roja o un gato curioso), un lugar (un puerto, una biblioteca o un patio de escuela) y al menos dos sentidos. Incluye una comparación.",
   "Mi abuelo pescador estaba en el puerto. Olía a sal y se oían las gaviotas. Sus manos eran ásperas como cuerdas. Sonreía mientras arreglaba la red.",
   ["personaje y lugar", "dos sentidos", "una comparación"], ["la descripción en el cuaderno"],
   ["solo adjetivos", "sin sentidos"], "Léela y pide a alguien que dibuje lo que imaginó."),
  "Describe con tres detalles un objeto de tu casa.",
  "Reescribe «el parque era lindo» con dos sentidos.")

# ------------------------------------------------------------------ clase 4
L(OA14, 4,
  "Este cuaderno y un lápiz.",
  "Aprenderé a escribir diálogos en una narración, con raya, verbos de habla y una puntuación correcta.",
  ["Sé escribir descripciones.", "Sé usar signos de interrogación y exclamación."],
  ["El diálogo es la conversación entre los personajes. En una narración, el diálogo muestra cómo son y qué sienten. Se escribe con raya (—) al comienzo de lo que dice cada personaje. Cada vez que cambia el que habla, empiezo una nueva línea con otra raya.",
   "Para decir quién habla, el narrador agrega una aclaración con un verbo de habla (dijo, preguntó, respondió, exclamó, susurró). La aclaración va después de la raya: —Vamos al parque —dijo Luis. Aquí no se pone punto después de «parque» y el punto final va después de «Luis». Si lo que se dice es pregunta o exclamación, se mantienen sus signos y la aclaración empieza con minúscula: —¿Vienes conmigo? —preguntó Ana.",
   "No todas las narraciones necesitan diálogo, pero cuando lo usamos conviene que sea breve y que diga algo importante: aclarar un conflicto, mostrar el carácter de un personaje o mover la trama. Un diálogo largo que no aporta cansa. Y cada personaje debe hablar como es: un niño pequeño no habla igual que un adulto."],
  [("diálogo", "conversación entre personajes"), ("raya", "el signo largo (—) que abre lo que dice un personaje"), ("verbo de habla", "verbo que indica cómo se dice algo"), ("narrador", "voz que cuenta la historia"), ("aclaración", "frase que dice quién habla")],
  [("Escribir un diálogo", "Escribe: Ana pregunta a Luis si viene al parque y Luis responde que sí.",
    ["Cada personaje habla en una línea.", "Uso raya antes de lo que dice.", "Agrego un verbo de habla."], "—¿Vienes al parque? —preguntó Ana.\n—Sí, voy —respondió Luis."),
   ("Puntuación del diálogo", "Elige la correcta: a) —¿Vienes? —preguntó Ana. b) —¿Vienes?— preguntó Ana.",
    ["La pregunta mantiene sus signos.", "La aclaración empieza con minúscula.", "Después de la pregunta va una raya con espacio."], "La a")],
  [("Escribir un diálogo sin raya.", "Se confunde con la narración.", "Abre con una raya cada intervención."),
   ("Poner punto antes de la aclaración.", "La aclaración sigue a lo que dijo el personaje.", "Elimina ese punto y cierra la oración al final.")],
  ([E("La raya (—) se usa al comienzo de lo que dice un personaje. ¿Verdadero o falso?", "Verdadero", "Marca el diálogo."),
    E("«Dijo», «preguntó» y «respondió», ¿son verbos de habla? Responde sí o no.", "Sí", "Indican cómo se dice algo."),
    E("Cuando cambia el que habla, ¿se empieza una línea nueva? Responde sí o no.", "Sí", "Así se distinguen los personajes.")],
   [E("Elige el diálogo bien escrito: a) —Hola —dijo Rosa. b) Hola dijo Rosa.", "a", "Usa raya y la aclaración."),
    E("—¿Dónde está mi gorro? —preguntó Tomás. ¿Quién habla?", "Tomás", "La aclaración lo dice."),
    E("—¡Qué sorpresa! —exclamó Lía. ¿Qué verbo de habla se usa?", "Exclamó", "Indica cómo lo dijo.")],
   [E("En un cuento escrito en pasado, ¿qué línea va: a) —Me gusta este libro —dijo Pía. b) —Me gusta este libro —dice Pía. Escribe la letra.", "a", "El cuento está en pasado, así que el verbo es «dijo»."),
    E("Elige la versión bien puntuada: a) —¿Vienes? —preguntó Ana. b) —¿Vienes? —Preguntó Ana.", "a", "La aclaración empieza con minúscula."),
    arith("En un diálogo, Ana habla 3 veces y Luis habla 4 veces. Cada intervención va en una línea distinta. ¿Cuántas líneas ocupa el diálogo?", "3+4", "Se suman las intervenciones de los dos personajes.", " líneas")],
   [E("Un estudiante escribe: «Hola dijo Pedro, ¿cómo estás?» sin raya. ¿Qué le falta: raya o más adjetivos?", "Raya", "Sin raya no se reconoce el diálogo."),
    E("Un diálogo de 12 líneas donde se saludan, se despiden y repiten lo mismo. ¿Aporta algo a la narración? Responde sí o no.", "No", "No avanza la trama.")],
   [E("Escribe la aclaración correcta: —Tengo frío —____ Ema en voz baja. Elige entre susurró y gritó.", "susurró", "Susurrar es hablar en voz baja."),
    E("Pasa a diálogo: Pablo dice que tiene hambre. Elige: a) —Tengo hambre —dijo Pablo. b) Dijo Pablo tengo hambre.", "a", "Usa raya y aclaración.")]),
  [E("Quieres mostrar que dos amigos se ponen de acuerdo para jugar. ¿Cuál diálogo sirve: —¿Jugamos a las escondidas? —preguntó Luis. —¡Dale! —respondió Ema. o —Hola. —Hola. —¿Todo bien? —Sí.", "El primero", "Avanza la trama con una propuesta y una respuesta.")],
  [E("¿Qué signo abre lo que dice un personaje?", "La raya", "Marca el diálogo."),
   E("Nombra un verbo de habla.", "Dijo, preguntó, respondió, exclamó o susurró", "Indican cómo se dice."),
   E("¿La aclaración después de una pregunta empieza con minúscula? Responde sí o no.", "Sí", "Es parte de la misma oración.")],
  ("Escribe un diálogo breve de al menos cuatro líneas entre dos personajes de tu elección (dos amigos, un abuelo y su nieta o un niño y su mascota) que quieren ponerse de acuerdo sobre qué hacer en la tarde. Usa raya, verbos de habla distintos y una pregunta.",
   "—¿Salimos a andar en bicicleta? —preguntó Camila.\n—Prefiero pintar —respondió Teo.\n—Podemos hacer las dos cosas —sugirió Camila.\n—Está bien —dijo Teo.",
   ["usa raya", "verbos de habla distintos", "puntuación correcta"], ["el diálogo en el cuaderno"],
   ["olvidar la raya", "repetir siempre «dijo»"], "Lee el diálogo en voz alta con otra persona, cada uno con un personaje."),
  "Escribe una pregunta y su respuesta con raya.",
  "Cambia los verbos de habla de tu diálogo por otros.")

# ------------------------------------------------------------------ clase 5
L(OA14, 5,
  "Este cuaderno y un lápiz.",
  "Aprenderé a distinguir un relato de experiencia personal, una noticia y un cuento, y a escribir una narración propia con inicio, desarrollo y desenlace.",
  ["Sé usar conectores, descripciones y diálogo.", "Sé armar un plan de narración."],
  ["Hay distintas narraciones. El relato de experiencia personal cuenta algo que me ocurrió, en primera persona, con sentimientos. La noticia informa un hecho real: lleva un titular, una entrada que responde qué pasó, quién, cuándo y dónde, y un cuerpo con más detalles. El cuento narra una historia inventada, con personajes, conflicto y desenlace.",
   "Cada una usa recursos distintos. La noticia cuenta con precisión y casi sin opiniones. El relato personal incluye lo que sentí. El cuento puede imaginar lo que no existe y usar diálogo y descripciones creativas. En todos conviene ordenar los hechos con conectores.",
   "Para escribir, sigo cuatro pasos: elijo el tipo de narración; planifico quién, dónde, cuándo, qué problema y cómo termina; escribo el borrador con conectores, una descripción y, si corresponde, diálogo; y lo reviso. El borrador no tiene que quedar perfecto: es la primera versión."],
  [("relato de experiencia personal", "narración en primera persona de algo que viví"), ("noticia", "texto que informa un hecho real"), ("titular", "título de una noticia"), ("entrada", "primer párrafo de una noticia"), ("borrador", "primera versión de un texto")],
  [("Distinguir el tipo", "Texto: «Ayer, en la plaza del barrio, se inauguró una biblioteca al aire libre. Asistieron cincuenta vecinos». ¿Es noticia o cuento?",
    ["Informa un hecho real.", "Dice dónde, cuándo y cuántos.", "Es una noticia."], "Noticia"),
   ("Escribir una entrada", "Hecho: un grupo de estudiantes plantó árboles en el patio el lunes. Escribe una entrada.",
    ["Qué pasó: plantaron árboles.", "Quién: un grupo de estudiantes.", "Cuándo y dónde: el lunes, en el patio."], "El lunes, un grupo de estudiantes plantó árboles en el patio")],
  [("Poner opiniones en una noticia.", "La noticia informa hechos.", "Cuenta qué pasó, quién, cuándo y dónde."),
   ("Contar un relato personal sin sentimientos.", "Pierde lo personal.", "Agrega lo que sentiste.")],
  ([E("Una noticia informa un hecho real. ¿Verdadero o falso?", "Verdadero", "Esa es su función."),
    E("«Había una vez un dragón que vivía en un volcán» ¿es un cuento o una noticia?", "Un cuento", "Es una historia inventada."),
    E("¿El titular es el título de la noticia? Responde sí o no.", "Sí", "Resume el hecho.")],
   [E("«Ayer me caí de la bicicleta y me sentí avergonzado». ¿Es un relato personal o una noticia?", "Un relato personal", "Está en primera persona y expresa un sentimiento."),
    E("¿Qué preguntas responde la entrada de una noticia: qué, quién, cuándo y dónde o solo cómo me sentí?", "Qué, quién, cuándo y dónde", "Resume los datos principales."),
    E("Un borrador es la primera versión de un texto. ¿Verdadero o falso?", "Verdadero", "Se puede mejorar después.")],
   [E("Entrada de noticia: «El sábado, en el parque, un perro rescató a un gatito atrapado en un árbol». ¿Dónde ocurrió?", "En el parque", "Lo dice la entrada."),
    E("Convierte en titular: a) «Perro rescata a gatito en el parque». b) «Me encantó cuando vi al perro». Escribe la letra.", "a", "Resume el hecho."),
    arith("Una noticia tiene un titular, una entrada de 1 párrafo y un cuerpo de 3 párrafos. ¿Cuántos párrafos tiene sin contar el titular?", "1+3", "Se suman entrada y cuerpo.", " párrafos")],
   [E("Un estudiante escribe una noticia que dice «Fue un día horrible y me dio mucha pena». ¿Qué debe cambiar: quitar su opinión y dar datos o agregar más sentimientos?", "Quitar su opinión y dar datos", "La noticia informa hechos."),
    E("Si quieres contar un hecho inventado con un dragón amable, ¿qué tipo de narración eliges: cuento o noticia?", "Cuento", "Una historia inventada es un cuento.")],
   [E("Elige los pasos en orden: a) escribir el borrador, b) planificar, c) revisar, d) elegir el tipo de narración. Escribe las letras.", "d, b, a, c", "Se elige, se planifica, se escribe y se revisa."),
    E("Quieres contar el día en que ayudaste a un vecino. Para mostrar lo que sentiste, ¿eliges relato personal o noticia?", "Relato personal", "Incluye sentimientos propios.")]),
  [E("Tu curso hizo una feria de libros el viernes en el gimnasio. Tienes que escribir una noticia. ¿Qué dato no puede faltar en la entrada: cuándo y dónde fue la feria o tu opinión sobre ella?", "Cuándo y dónde fue la feria", "Son datos básicos de la noticia.")],
  [E("¿Qué responde la entrada de una noticia?", "Qué pasó, quién, cuándo y dónde", "Resume los datos principales."),
   E("¿Qué es un borrador?", "La primera versión de un texto", "Se puede mejorar."),
   E("¿Un relato personal puede incluir sentimientos? Responde sí o no.", "Sí", "Cuenta una experiencia propia.")],
  ("Escribe un borrador de una narración de al menos seis oraciones. Elige: a) un relato personal sobre un día especial; b) una noticia sobre un hecho inventado del colegio; o c) un cuento sobre un animal que habla. Incluye inicio, desarrollo, desenlace, un conector de tiempo y una descripción. Si usas diálogo, escríbelo con raya.",
   "Opción c: Un zorro llegó al pueblo. Tenía el pelaje rojo como una zanahoria. De pronto escuchó llorar a un niño. Primero se acercó despacio. Luego le mostró el camino de vuelta a casa. Finalmente, el niño le dio las gracias.",
   ["elige el tipo", "tiene inicio, desarrollo y desenlace", "usa conector y descripción"], ["el borrador en el cuaderno"],
   ["sin desenlace", "mezclar opiniones en la noticia"], "Lee tu borrador a alguien y pide que diga cuál es el conflicto."),
  "Escribe un titular para un hecho de tu día.",
  "Cambia tu borrador de cuento por una noticia sobre el mismo hecho.")

# ------------------------------------------------------------------ clase 6
L(OA14, 6,
  "Este cuaderno y un lápiz. El borrador de la clase anterior, si lo tienes.",
  "Aprenderé a revisar una narración con una lista de verificación y a mejorarla con retroalimentación.",
  ["Sé escribir una narración con inicio, desarrollo y desenlace.", "Sé usar conectores, descripciones y diálogo."],
  ["Revisar es leer un texto para mejorarlo. Una lista de verificación ayuda a no olvidar nada. Para una narración pregunto: ¿tiene inicio, desarrollo y desenlace?, ¿hay un conflicto?, ¿usé conectores?, ¿describí a un personaje o el ambiente?, ¿el diálogo tiene raya y verbos de habla?, ¿las oraciones empiezan con mayúscula y terminan con punto?",
   "La retroalimentación es el comentario de otra persona que me ayuda a mejorar. Es útil cuando dice qué está bien, qué se puede cambiar y cómo. «Está bonito» no basta. «Me gustó la descripción de la casa; el final no resuelve el problema, podrías contar cómo lo solucionó» sí ayuda.",
   "Después de recibir comentarios, elijo uno o dos cambios y los hago. No tengo que aceptar todo, pero sí revisar si el comentario tiene razón. Al terminar, comparo la primera versión con la nueva y veo qué mejoró. Escribir de nuevo es parte normal de escribir bien."],
  [("revisar", "leer un texto para mejorarlo"), ("lista de verificación", "preguntas que reviso una por una"), ("retroalimentación", "comentario que ayuda a mejorar"), ("versión", "forma de un texto en un momento"), ("coherente", "que tiene sentido de principio a fin")],
  [("Revisar con la lista", "Borrador: «Tomás fue al parque. Jugó. Volvió». Revisa: ¿tiene conflicto? ¿tiene descripción?",
    ["No hay problema.", "No hay descripción.", "Le faltan conflicto y descripción."], "No: le faltan conflicto y descripción"),
   ("Retroalimentación útil", "Comentario A: «Está bien». Comentario B: «Tu inicio presenta bien al personaje; falta que cuentes cómo resolvió el problema». ¿Cuál ayuda más?",
    ["A no dice nada.", "B dice lo bueno y lo que mejorar.", "B sugiere un cambio."], "El comentario B")],
  [("Corregir solo la ortografía y no el contenido.", "Un texto puede tener buenas tildes y no tener conflicto.", "Revisa primero las ideas y la estructura."),
   ("Rechazar los comentarios sin pensarlos.", "Pierdes oportunidades de mejora.", "Evalúa si el comentario tiene razón.")],
  ([E("Una lista de verificación se revisa pregunta por pregunta. ¿Verdadero o falso?", "Verdadero", "Así no se olvida ningún punto."),
    E("Un comentario útil dice qué está bien y qué se puede mejorar. ¿Verdadero o falso?", "Verdadero", "Es retroalimentación específica."),
    E("¿Escribir de nuevo un texto es parte normal de escribir bien? Responde sí o no.", "Sí", "Se mejora con las versiones.")],
   [E("Borrador: «Lía salió. Caminó. Llegó». ¿Tiene conflicto? Responde sí o no.", "No", "Solo narra acciones."),
    E("Comentario: «Agrega un diálogo con raya en el momento en que los amigos discuten». ¿Es un comentario concreto? Responde sí o no.", "Sí", "Dice qué cambiar y dónde."),
    E("Comentario: «Está lindo». ¿Dice cómo mejorar? Responde sí o no.", "No", "No es específico.")],
   [E("Lista: inicio sí, conflicto no, conectores sí, descripción sí, diálogo no corresponde, ortografía sí. ¿Qué debe mejorar?", "El conflicto", "Es el único que falló."),
    E("Un texto dice: «De pronto se apagó la luz. Luego salimos con una linterna. Finalmente volvió la luz». ¿Qué conectores usa?", "De pronto, luego y finalmente", "Son conectores de tiempo."),
    arith("Una lista tiene 8 preguntas y tu texto cumple 6. ¿Cuántas preguntas debes mejorar?", "8-6", "Se restan las cumplidas del total.", " preguntas")],
   [E("Pedro recibió el comentario «Falta el desenlace» y borró el final. ¿Lo mejoró? Responde sí o no.", "No", "Debía agregar cómo se resuelve."),
    E("Dos revisiones: A «Corregí tildes». B «Agregué un conflicto y un final». ¿Cuál mejora más la narración?", "B", "Mejora la estructura.")],
   [E("Borrador: «Ema fue a la playa. Había mucha gente. Encontró una conchita. Se fue». Escribe un comentario de retroalimentación: elige el mejor. a) «Muy corto». b) «Buen comienzo; agrega un problema, por ejemplo que perdió la conchita, y cómo lo resolvió». Escribe la letra.", "b", "Dice lo bueno y propone un cambio concreto."),
    E("Después de recibir comentarios, ¿qué haces: eliges uno o dos cambios y los haces o borras todo el texto?", "Eliges uno o dos cambios y los haces", "Así mejoras de a poco.")]),
  [E("Compañero A te dice: «Tu historia no tiene conflicto». Compañero B te dice: «Tu historia es de las mejores». ¿Cuál comentario te ayuda a mejorar?", "El de A", "Señala algo concreto a mejorar.")],
  [E("¿Para qué sirve una lista de verificación?", "Para revisar sin olvidar nada", "Se responde pregunta por pregunta."),
   E("¿Qué debe incluir un buen comentario?", "Lo bueno y lo que mejorar", "Así el comentario es específico y ayuda."),
   E("¿Revisar sirve para mejorar? Responde sí o no.", "Sí", "Ese es su propósito.")],
  ("Toma tu borrador de la clase 5 o usa este texto original: «Ana fue a la feria con su amiga Rosa. Compraron manzanas. Volvieron a casa». Revísalo con la lista: inicio, conflicto, conectores, descripción, diálogo, puntuación. Escribe tres comentarios de retroalimentación (uno bueno y dos para mejorar) y reescribe el texto con al menos dos mejoras.",
   "Bueno: presenta a los personajes. Mejorar: falta un problema, como perder el monedero. Mejorar: agregar una descripción de la feria. Nueva versión: Ana fue a la feria con su amiga Rosa. Olía a fruta fresca. De pronto, Ana no encontraba el monedero. Lo buscó y finalmente lo halló en la bolsa.",
   ["usa la lista", "tres comentarios", "reescribe con mejoras"], ["los comentarios y la nueva versión en el cuaderno"],
   ["comentarios vagos", "reescribir sin cambios"], "Muestra las dos versiones a alguien y pregúntale cuál le gusta más."),
  "Revisa una narración con las preguntas de la lista.",
  "Escribe una retroalimentación para un texto de una persona de tu casa.")
